PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS learning_goals (id TEXT PRIMARY KEY, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES learning_goals(id) ON DELETE CASCADE, phase TEXT NOT NULL, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_session ON messages(session_id,created_at);
CREATE TABLE IF NOT EXISTS diagnostic_answers (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, question TEXT NOT NULL, answer TEXT NOT NULL, reasoning TEXT NOT NULL, evaluation TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS curricula (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES learning_goals(id) ON DELETE CASCADE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, curriculum_id TEXT NOT NULL REFERENCES curricula(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL, prerequisites TEXT NOT NULL, objectives TEXT NOT NULL, difficulty TEXT NOT NULL, status TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS exercises (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES learning_goals(id) ON DELETE CASCADE, topic_id TEXT REFERENCES topics(id) ON DELETE SET NULL, kind TEXT NOT NULL, prompt TEXT NOT NULL, solution TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, exercise_id TEXT NOT NULL REFERENCES exercises(id) ON DELETE CASCADE, answer TEXT NOT NULL, reasoning TEXT NOT NULL, evaluation TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_nodes (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES learning_goals(id) ON DELETE CASCADE, kind TEXT NOT NULL, name TEXT NOT NULL, statement TEXT NOT NULL, source_session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL, source_message_id TEXT REFERENCES messages(id) ON DELETE SET NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_edges (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES learning_goals(id) ON DELETE CASCADE, premises TEXT NOT NULL, conclusion_id TEXT NOT NULL REFERENCES knowledge_nodes(id) ON DELETE CASCADE, source_session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_executions (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL REFERENCES learning_goals(id) ON DELETE CASCADE, status TEXT NOT NULL, step_id TEXT NOT NULL, input TEXT NOT NULL, output TEXT, error TEXT, retry_count INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_executions (id TEXT PRIMARY KEY, session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL, provider TEXT NOT NULL, model TEXT NOT NULL, operation TEXT NOT NULL, status TEXT NOT NULL, duration_ms INTEGER NOT NULL, metadata TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences (key TEXT PRIMARY KEY, value TEXT NOT NULL);
